package com.example.gdxsim;

import com.badlogic.gdx.ApplicationAdapter;
import com.badlogic.gdx.Gdx;
import com.badlogic.gdx.files.FileHandle;

import java.io.IOException;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.io.Writer;
import java.nio.charset.StandardCharsets;
import java.util.Locale;
import java.util.Properties;

/**
 * A fully deterministic 2D point-mass simulation driven by the libGDX headless
 * backend. One call to {@link #render()} advances exactly one simulation tick
 * using a fixed time step read from the configuration file. The final state is
 * written to the output file from {@link #dispose()} so it is guaranteed to be
 * flushed before the JVM exits.
 */
public class SimListener extends ApplicationAdapter {

    private final String configPath;
    private final String outputPath;

    // Simulation parameters (parsed from config).
    private int ticks;
    private double dt;
    private double x, y;
    private double vx, vy;
    private double ay;

    // Number of ticks performed so far.
    private int tickCount;

    public SimListener(String configPath, String outputPath) {
        this.configPath = configPath;
        this.outputPath = outputPath;
    }

    @Override
    public void create() {
        FileHandle handle = Gdx.files.absolute(configPath);
        Properties props = new Properties();
        try (var in = handle.read()) {
            props.load(in);
        } catch (IOException e) {
            throw new RuntimeException("Failed to read config file: " + configPath, e);
        }

        ticks = Integer.parseInt(props.getProperty("ticks").trim());
        dt = Double.parseDouble(props.getProperty("dt").trim());
        x = Double.parseDouble(props.getProperty("position_x").trim());
        y = Double.parseDouble(props.getProperty("position_y").trim());
        vx = Double.parseDouble(props.getProperty("velocity_x").trim());
        vy = Double.parseDouble(props.getProperty("velocity_y").trim());
        ay = Double.parseDouble(props.getProperty("gravity_y").trim());

        if (ticks < 0) {
            throw new IllegalArgumentException("ticks must be >= 0");
        }

        tickCount = 0;
    }

    @Override
    public void render() {
        if (tickCount >= ticks) {
            return;
        }

        // Symplectic Euler: update velocity first, then position using new velocity.
        double ax = 0.0;
        vx += ax * dt;
        vy += ay * dt;
        x += vx * dt;
        y += vy * dt;

        tickCount++;

        if (tickCount >= ticks) {
            Gdx.app.exit();
        }
    }

    @Override
    public void dispose() {
        StringBuilder sb = new StringBuilder();
        sb.append(String.format(Locale.ROOT, "final_x=%.6f%n", x));
        sb.append(String.format(Locale.ROOT, "final_y=%.6f%n", y));
        sb.append(String.format(Locale.ROOT, "final_vx=%.6f%n", vx));
        sb.append(String.format(Locale.ROOT, "final_vy=%.6f%n", vy));
        sb.append(String.format(Locale.ROOT, "ticks=%d%n", tickCount));

        FileHandle out = Gdx.files.absolute(outputPath);
        try (OutputStream os = out.write(false);
             Writer writer = new OutputStreamWriter(os, StandardCharsets.UTF_8)) {
            writer.write(sb.toString());
        } catch (IOException e) {
            throw new RuntimeException("Failed to write output file: " + outputPath, e);
        }
    }
}

package com.example.gdxsim;

import com.badlogic.gdx.backends.headless.HeadlessApplication;
import com.badlogic.gdx.backends.headless.HeadlessApplicationConfiguration;

/**
 * Bootstrap entry point. Constructs a {@link HeadlessApplication} running the
 * deterministic simulation {@link SimListener}. The config and output paths are
 * passed as command-line arguments: {@code <config-path> <output-path>}.
 *
 * <p>After the simulation finishes, {@link SimListener#render()} calls
 * {@code Gdx.app.exit()} which asynchronously stops the main loop. We join the
 * main loop thread here so the JVM only exits once {@code dispose()} (which
 * writes the output file) has completed.</p>
 */
public class Main {

    public static void main(String[] args) throws InterruptedException {
        if (args.length < 2) {
            System.err.println("Usage: Main <config-path> <output-path>");
            System.exit(2);
        }

        String configPath = args[0];
        String outputPath = args[1];

        HeadlessApplicationConfiguration config = new HeadlessApplicationConfiguration();
        // Run the main loop as fast as possible; ticks are driven by our own
        // counter, not by wall-clock pacing.
        config.updatesPerSecond = 0;

        SimListener listener = new SimListener(configPath, outputPath);
        HeadlessApplication app = new HeadlessApplication(listener, config);

        // Block until the main loop thread terminates, ensuring dispose() has
        // run and the output file has been flushed before the JVM exits.
        app.join();
    }
}

